BEGIN;
CREATE TABLE IF NOT EXISTS normalized_security_events(id UUID PRIMARY KEY,organization_id UUID NOT NULL,idempotency_key TEXT NOT NULL,source TEXT NOT NULL,event_type TEXT NOT NULL,schema_version INTEGER NOT NULL,observed_at TIMESTAMPTZ NOT NULL,ingested_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),correlation_id UUID,raw_event_hash CHAR(64) NOT NULL,payload JSONB NOT NULL,ingested_by UUID,duplicate_count INTEGER NOT NULL DEFAULT 0,processing_status TEXT NOT NULL DEFAULT 'PENDING',last_error TEXT,UNIQUE(organization_id,idempotency_key));
CREATE INDEX IF NOT EXISTS idx_security_events_org_observed ON normalized_security_events(organization_id,observed_at DESC);
CREATE INDEX IF NOT EXISTS idx_security_events_pending ON normalized_security_events(processing_status,ingested_at) WHERE processing_status IN('PENDING','RETRY');
CREATE TABLE IF NOT EXISTS security_entities(id UUID PRIMARY KEY,organization_id UUID NOT NULL,entity_type TEXT NOT NULL,entity_value TEXT NOT NULL,attributes JSONB NOT NULL DEFAULT '{}',first_seen_at TIMESTAMPTZ NOT NULL,last_seen_at TIMESTAMPTZ NOT NULL,UNIQUE(organization_id,entity_type,entity_value));
CREATE TABLE IF NOT EXISTS security_event_entities(event_id UUID NOT NULL,entity_id UUID NOT NULL,organization_id UUID NOT NULL,PRIMARY KEY(event_id,entity_id));
CREATE TABLE IF NOT EXISTS security_entity_edges(id UUID PRIMARY KEY,organization_id UUID NOT NULL,source_entity_id UUID NOT NULL,target_entity_id UUID NOT NULL,relationship_type TEXT NOT NULL,first_seen_at TIMESTAMPTZ NOT NULL,last_seen_at TIMESTAMPTZ NOT NULL,event_count INTEGER NOT NULL DEFAULT 1,confidence NUMERIC(5,4) NOT NULL DEFAULT 1,UNIQUE(organization_id,source_entity_id,target_entity_id,relationship_type));
CREATE TABLE IF NOT EXISTS security_event_outbox(id UUID PRIMARY KEY,organization_id UUID NOT NULL,event_id UUID NOT NULL,topic TEXT NOT NULL,payload JSONB NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING',attempt_count INTEGER NOT NULL DEFAULT 0,next_attempt_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),lease_owner TEXT,lease_until TIMESTAMPTZ,last_error TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),published_at TIMESTAMPTZ);
CREATE INDEX IF NOT EXISTS idx_security_outbox_claim ON security_event_outbox(status,next_attempt_at,created_at);
CREATE TABLE IF NOT EXISTS security_event_dead_letters(id UUID PRIMARY KEY,organization_id UUID NOT NULL,event_id UUID NOT NULL,outbox_id UUID,reason TEXT NOT NULL,payload JSONB NOT NULL,attempt_count INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),replayed_at TIMESTAMPTZ);
COMMIT;
